function ilgCategoryTabsLoadMore(e){e.preventDefault();e.stopPropagation();var data={action:'ilg_category_tabs',security:IlgCategoryTabsAjax.security,slug:$(this).data('slug'),offset:$(this).data('offset'),limit:$(this).data('limit'),style:$(this).data('style'),};$el=$(this).closest('.tab-pane');$(this).remove();$el.html($el.html()+'<span class="ilg-category-tabs-loading">loading ...</span>');$.post(IlgCategoryTabsAjax.ajaxurl,data,function(response){$('.ilg-category-tabs-loading').remove();$el.append(response);$('.ilg-gategory-tabs-load-more').unbind('click').on('click',ilgCategoryTabsLoadMore);$(document.body).trigger('post-load');});return false;}
jQuery(document).ready(function($){$('.ilg-gategory-tabs-load-more').unbind('click').on('click',ilgCategoryTabsLoadMore);});